```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	filePath := filepath.Join(filepath.Dir(sourceFile), sourceFile)
	file, err := os.Open(filePath)
	if err != nil {
		fmt.Printf("Error opening file %s: %v\n", filePath, err)
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var structType string
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "// Struct Type:") {
			structType = line[len("// Struct Type:"):].trim()
			break
		}
	}

	if structType == "" {
		fmt.Printf("No struct found in the file.\n")
		return
	}

	// Output the generated AVRO schema
	fmt.Printf("%s\n", genAvroSchema(structName, structType))
}

func trim(s string) string {
	start := s.Index('"')
	end := s.LastIndex('"')

	return s[start+1 : end]
}

func genAvroSchema(name string, typeName string) string {
	schema := fmt.Sprintf(`{
    "type": "%s",
    "name": "%s",
    "fields": [
        {"name":"%s","type":["null"],"default":"undefined"}
    ]
}`, typeName, name, name)
	return schema
}
```

